// Plugin de instrumento para Demo Kit · Espiral sonora
// Un Shepard–Risset a velocidad constante (el glissando que sube o baja «para siempre») donde además cada octava
// viaja de izquierda a derecha con una fase distinta: la espiral gira en el espacio mientras sube o baja en altura.
// Pensado para escuchar con audífonos durante ~40–60 s. Al detenerse y dejar un tono quieto (octavas = 0), algunas personas
// perciben que el tono quieto «se mueve» en sentido contrario: es un postefecto de movimiento espectral (como el de la espiral visual).
// Es un efecto de percepción, breve y que varía de persona a persona.
//   · «octavas recorridas» entero → la nota termina con la pila alineada igual que empezó (empalma con una nota quieta)
//   · «giro» son vueltas por segundo del movimiento espacial; «apertura» cuánto abre el panorama (0 = mono)
//   · volumen moderado: el efecto no necesita volumen alto
registerInstrument({
  id: 'espiral_sonora',
  name: 'Espiral sonora',
  kind: 'melodic',
  desc: 'Shepard–Risset a velocidad constante con cada octava girando en el espacio (L↔R). Postefecto de movimiento espectral.',
  params: [
    {k:'gain',   label:'Ganancia',                       min:0,   max:1,   step:.005, def:.5},
    {k:'octs',   label:'Octavas recorridas en la nota',  min:0,   max:80,  step:1,    def:9},
    {k:'dir',    label:'Dirección',                      type:'choice', opts:['Baja','Sube'], vals:[-1,1], def:-1},
    {k:'spin',   label:'Giro espacial (vueltas/s)',      min:0,   max:.5,  step:.005, def:.08},
    {k:'spread', label:'Apertura del panorama',          min:0,   max:1,   step:.01,  def:.8},
    {k:'parts',  label:'Parciales (octavas de ancho)',   min:4,   max:12,  step:1,    def:8},
    {k:'bell',   label:'Estrechez de la ventana',        min:.5,  max:4,   step:.05,  def:1.5},
    {k:'atk',    label:'Entrada (s)',                    min:.005,max:12,  step:.005, def:6},
    {k:'rel',    label:'Salida (s)',                     min:.02, max:8,   step:.01,  def:.3}
  ],
  play(K, n) {
    const p = n.p, sr = n.sr || 44100, TAU = 6.2831853, N = Math.round(p.parts), len = n.len, M = Math.floor((len + p.rel) * sr);
    const fB = n.hz / Math.pow(2, N / 2), r = p.dir * p.octs / len, ex = 2 * p.bell;     // octavas/s, constante
    const ph = new Float64Array(N); for (let i = 0; i < N; i++) ph[i] = (K.rnd() + 1) / 2;
    const A = new Float32Array(M), B = new Float32Array(M);                              // canal izquierdo y derecho
    for (let k = 0; k < M; k++) {
      const t = k / sr, x = r * Math.min(t, len);
      const a = Math.min(1, t / p.atk), env = a * a * (3 - 2 * a) * (t > len ? Math.max(0, 1 - (t - len) / p.rel) : 1);
      let l = 0, rr = 0;
      for (let i = 0; i < N; i++) {
        let u = (i + x) % N; if (u < 0) u += N;
        const f = fB * Math.pow(2, u); ph[i] += f / sr; ph[i] -= Math.floor(ph[i]);
        if (f >= sr * .45) continue;
        const s = Math.pow(Math.sin(Math.PI * u / N), ex) * Math.sin(TAU * ph[i]);
        const th = (p.spread * Math.sin(TAU * (p.spin * t + i / N)) + 1) * Math.PI / 4;  // la octava i tiene su propia fase de giro
        l += s * Math.cos(th); rr += s * Math.sin(th);
      }
      const g = env * (.55 / Math.sqrt(N)); A[k] = l * g; B[k] = rr * g;
    }
    K.add(n.buf, n.t, len + p.rel, t => A[Math.round(t * sr)] || 0, n.a * p.gain, -1);   // izquierda total
    K.add(n.buf, n.t, len + p.rel, t => B[Math.round(t * sr)] || 0, n.a * p.gain, 1);    // derecha total
  }
});

// Plugin de instrumento para Demo Kit · Ruido con muesca
// Ruido de banda ancha al que se le recorta un hueco (la «muesca») alrededor de una frecuencia.
// Es el estímulo clásico del «tono de Zwicker» (1964, «imagen negativa» auditiva): al apagarse el ruido y quedar
// en silencio, algunas personas oyen unos segundos un tono tenue cerca de la frecuencia del hueco.
// No funciona igual en todos los oídos ni a todos los volúmenes: úsalo suave, con silencio después, y no más de unos 10 s.
//   · el recorte se hace en el espectro (FFT): bordes suaves, profundidad configurable en dB
//   · «inclinación» baja los agudos para que el ruido sea tipo rosa y no raspe
registerInstrument({
  id: 'ruido_con_muesca',
  name: 'Ruido con muesca',
  kind: 'perc',
  desc: 'Ruido con un hueco espectral: tras apagarlo, el silencio puede traer un tono fantasma (tono de Zwicker).',
  params: [
    {k:'gain',  label:'Ganancia',                   min:0,   max:1,    step:.005, def:.3},
    {k:'fc',    label:'Centro de la muesca (Hz)',   min:200, max:8000, step:10,   def:3150},
    {k:'width', label:'Ancho de la muesca (oct.)',  min:.1,  max:2,    step:.05,  def:.5},
    {k:'depth', label:'Profundidad (dB)',           min:10,  max:80,   step:1,    def:60},
    {k:'lo',    label:'Corte grave (Hz)',           min:20,  max:1000, step:10,   def:100},
    {k:'hi',    label:'Corte agudo (Hz)',           min:2000,max:16000,step:100,  def:9000},
    {k:'tilt',  label:'Inclinación (dB/octava)',    min:0,   max:9,    step:.5,   def:3},
    {k:'fade',  label:'Entrada y salida (s)',       min:.02, max:3,    step:.01,  def:.3}
  ],
  play(K, n) {
    const p = n.p, sr = n.sr || 44100, len = n.len;
    let N = 4096; while (N < len * sr + 8) N <<= 1;
    const re = new Float64Array(N), im = new Float64Array(N);
    for (let i = 0; i < N; i++) re[i] = K.rnd();
    const fft = (a, b) => {
      for (let i = 1, j = 0; i < N; i++) { let bit = N >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) { let t = a[i]; a[i] = a[j]; a[j] = t; t = b[i]; b[i] = b[j]; b[j] = t; } }
      for (let m = 2; m <= N; m <<= 1) {
        const ang = -2 * Math.PI / m, wr = Math.cos(ang), wi = Math.sin(ang), h = m >> 1;
        for (let i = 0; i < N; i += m) { let cr = 1, ci = 0;
          for (let j = 0; j < h; j++) {
            const x = i + j, y = x + h, vr = a[y] * cr - b[y] * ci, vi = a[y] * ci + b[y] * cr;
            a[y] = a[x] - vr; b[y] = b[x] - vi; a[x] += vr; b[x] += vi;
            const t = cr * wr - ci * wi; ci = cr * wi + ci * wr; cr = t; } } }
    };
    const sm = x => { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); };
    const floor = Math.pow(10, -p.depth / 20), E = .08;               // bordes de .08 octavas
    const shape = f => {
      if (f < 1) return 0;
      const d = Math.abs(Math.log2(f / p.fc)), notch = floor + (1 - floor) * sm((d - p.width / 2 + E) / (2 * E));
      const band = sm((Math.log2(f / p.lo) + .25) / .5) * sm((Math.log2(p.hi / f) + .25) / .5);
      return notch * band * Math.pow(10, -p.tilt * Math.log2(f / 1000) / 20);
    };
    fft(re, im);
    for (let k = 0; k <= N / 2; k++) { const g = shape(k * sr / N); re[k] *= g; im[k] *= g; if (k > 0 && k < N / 2) { re[N - k] *= g; im[N - k] *= g; } }
    for (let i = 0; i < N; i++) im[i] = -im[i];                       // inversa = FFT del conjugado
    fft(re, im);
    let e = 0; const M = Math.min(N, Math.floor(len * sr)); for (let i = 0; i < M; i++) e += re[i] * re[i];
    const norm = .35 / Math.sqrt(e / M + 1e-30);
    K.add(n.buf, n.t, len, t => {
      const x = Math.min(1, t / p.fade, (len - t) / p.fade), env = x * x * (3 - 2 * Math.max(0, x));
      return (re[Math.round(t * sr)] || 0) * norm * env;
    }, n.a * p.gain, n.pan);
  }
});
